function renderIntelTonight(top,shortest,activeCovers){return '<div class="card intelHero"><div class="intelTop"><b>Best live move</b><span class="muted">Right now</span></div><div class="intelMove"><div class="intelVenue"><b>'+esc(top.name)+'</b><div class="muted">'+level(top).label+' · '+top.event+'</div></div><div class="intelMetric">'+top.wait+' min</div></div></div><div class="intelGrid"><div class="intelTile"><span class="muted">Shortest line</span><div><b>'+esc(shortest.name)+'</b><small>'+(shortest.wait?shortest.wait+" min":"No line")+'</small></div></div><div class="intelTile"><span class="muted">Cover alerts</span><div><b>'+(activeCovers||"None")+'</b><small>'+(activeCovers?"Active tonight":"Hidden unless enabled")+'</small></div></div></div>'}
